function sponsor_count(mysqli $conn, string $sql): int { try { $r=$conn->query($sql); if(!$r)return 0; $row=$r->fetch_assoc();$r->free();return (int)($row['total']??0);}catch(Throwable $e){error_log('[Sponsor Portal] '.$e->getMessage());return 0;} }
function sponsor_rows(mysqli $conn, string $sql): array { try {$r=$conn->query($sql);if(!$r)return [];$rows=$r->fetch_all(MYSQLI_ASSOC);$r->free();return $rows;}catch(Throwable $e){error_log('[Sponsor Portal] '.$e->getMessage());return [];} }
function sponsor_e($v): string { return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); }
function sponsor_status(string $status): string { return ucwords(str_replace('_',' ',$status)); }
function sponsor_date($value): string { if(!$value || $value==='0000-00-00')return '—'; $t=strtotime((string)$value);return $t?date('d M Y',$t):'—'; }
function sponsor_table_exists(mysqli $conn,string $table): bool { $safe=$conn->real_escape_string($table);$r=$conn->query("SHOW TABLES LIKE '{$safe}'");$ok=$r && $r->num_rows>0;if($r)$r->free();return $ok; }
