ed?'Show menu':'Hide menu';menuBtn.setAttribute('aria-label',label);menuBtn.setAttribute('title',label);menuBtn.setAttribute('aria-expanded',String(!collapsed));const labelNode=menuBtn.querySelector('.toggle-label');if(labelNode)labelNode.textContent=label;}}function setMobileSidebarState(open){sidebar?.classList.toggle('open',open);overlay?.classList.toggle('open',open);if(menuBtn){const label=open?'Hide menu':'Show menu';menuBtn.setAttribute('aria-expanded',String(open));menuBtn.setAttribute('aria-label',label);menuBtn.setAttribute('title',label);const labelNode=menuBtn.querySelector('.toggle-label');if(labelNode)labelNode.textContent=label;}}try{if(window.innerWidth>=761)setDesktopSidebarState(localStorage.getItem(sidebarKey)==='1',false)}catch(e){}menuBtn?.addEventListener('click',()=>{if(window.innerWidth<761){setMobileSidebarState(!sidebar?.classList.contains('open'));}else{setDesktopSidebarState(!document.body.classList.contains('sp-sidebar-collapsed'));}});overlay?.addEventListener('click',()=>setMobileSidebarState(false));window.addEventListener('resize',()=>{if(window.innerWidth>=761){setMobileSidebarState(false);try{setDesktopSidebarState(localStorage.getItem(sidebarKey)==='1',false)}catch(e){setDesktopSidebarState(false,false)}}else{document.body.classList.remove('sp-sidebar-collapsed')}});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&window.innerWidth<761)setMobileSidebarState(false)});function applyTableFilters(table){if(!table)return;const search=document.querySelector('[data-search="#'+table.id+'"]');const status=document.querySelector('[data-filter-status="#'+table.id+'"]')||document.querySelector('[data-filter-status]');const q=(search?.value||'').trim().toLowerCase();const selected=status?.value||'';table.querySelectorAll('tbody tr').forEach(row=>{const text=row.innerText.toLowerCase();const statusValue=row.dataset.statusRow||'';row.hidden=!(text.includes(q)&&(!selected||statusValue===selected));});}document.querySelectorAll('[data-search]').forEach(input=>{input.addEventListener('input',()=>applyTableFilters(document.querySelector(input.dataset.search)));});document.querySelectorAll('[data-filter-status]').forEach(select=>{if(!select.dataset.table)select.dataset.table=select.closest('.sp-card')?.querySelector('table')?.id||'';select.addEventListener('change',()=>applyTableFilters(document.getElementById(select.dataset.table)||document.querySelector('table')));});document.querySelectorAll('table thead th').forEach(th=>{const table=th.closest('table');if(!table?.id)return;th.tabIndex=0;th.setAttribute('role','button');th.title='Sort by '+th.innerText.trim();const sort=()=>{const tbody=table.tBodies[0];if(!tbody)return;const idx=[...th.parentElement.children].indexOf(th);const asc=th.dataset.sort!=='asc';[...tbody.rows].sort((a,b)=>{const x=(a.cells[idx]?.innerText||'').trim();const y=(b.cells[idx]?.innerText||'').trim();const nx=Number(x.replace(/[^0-9.-]/g,''));const ny=Number(y.replace(/[^0-9.-]/g,''));if(x!==''&&y!==''&&!Number.isNaN(nx)&&!Number.isNaN(ny)&&/[0-9]/.test(x)&&/[0-9]/.test(y))return asc?nx-ny:ny-nx;return asc?x.localeCompare(y,undefined,{numeric:true,sensitivity:'base'}):y.localeCompare(x,undefined,{numeric:true,sensitivity:'base'});}).forEach(row=>tbody.appendChild(row));th.dataset.sort=asc?'asc':'desc';table.querySelectorAll('thead th').forEach(other=>{if(other!==th)delete other.dataset.sort;});};th.addEventListener('click',sort);th.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();sort();}});});})();</script></body></html><?php }
